const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([49.2915, -12.349]); // Arrachart, Madagascar
  const startDate = '2020-01-01';
  const endDate = '2020-02-01';

  // 2. Data Acquisition - CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(point);

  const collectionSize = chirps.size().getInfo();
  console.log(`January 2020 images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation for the month
  const monthlyPrecip = chirps.sum();

  // Check pixel count
  const pixelCount = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get precipitation and convert mm to inches
  const precipMm = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const precipInches = precipMm / 25.4; // Convert mm to inches
  console.log(`Total rainfall: ${precipInches.toFixed(2)} inches`);

  // 5. Validation & Final Answer
  if (precipInches === null || precipInches === undefined || isNaN(precipInches)) {
    console.log("<answer>C3</answer>");
  } else if (precipInches > 22) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
